/// @title A router with its routes in its own code: the cheapest dispatch, verified by Sourcify
/// @author Ronan Sandford
/// @notice Create an immutable route and delegate function calls to their respective
///  implementations, up to 256 implementations and as many selectors as a deployment can carry:
///  about 4,800 under EIP-170's 24,576 bytes of code, and, on a chain with EIP-3860 (Shanghai
///  and later), about 1,460, since the constructor takes the routes ABI-encoded (32 bytes a
///  selector) and init code is at most 49,152 bytes there. A lookup reads the router's own code
///  (CODECOPY): no storage read and no other account touched, the cheapest of the routers here.
/// @dev The deployed code is `InlineRouterDispatch`'s runtime code followed by the routes, so it
///  is longer than this contract's compiled runtime code: a verifier must match it by its
///  creation code. Sourcify (and Blockscout, which uses it) does; Etherscan, which matches the
///  runtime code, cannot. Use `Router` where Etherscan verification matters.
contract InlineRouter {
	/// @param routes define the routing (see `Routes`)
	constructor(Routes memory routes) {
		RouterRoutes.check(routes);
		uint256 numImplementations = routes.implementations.length;
		uint256 numSigs = routes.sigMap.length;

		bytes memory dispatch = type(InlineRouterDispatch).runtimeCode;
		uint256 codeSize = dispatch.length + numImplementations * 20 + numSigs * 5 + 24;
		require(codeSize <= 24576, 'TOO_MANY_ROUTES');

		bytes memory code = new bytes(codeSize);
		uint256 out;
		assembly {
			out := add(code, 32)
			// the dispatch code, a word at a time (the last word may spill past it, and the
			// routes written next overwrite the spill)
			let src := add(dispatch, 32)
			for {
				let i := 0
			} lt(i, mload(dispatch)) {
				i := add(i, 32)
			} {
				mstore(add(out, i), mload(add(src, i)))
			}
		}
		uint256 p = RouterRoutes.pack(routes, out + dispatch.length);
		address fallbackImplementation = routes.fallbackImplementation;
		assembly {
			mstore(p, or(or(shl(96, fallbackImplementation), shl(80, numImplementations)), shl(64, numSigs)))
			return(out, codeSize)
		}
	}
}
